function decorateThumbs(root=document){for(const el of $$('[data-r29-thumb]:not([data-r29-thumb-ready])',root)){el.dataset.r29ThumbReady='1';if(!el.dataset.r29Thumb)continue;const observe=()=>{thumbQueue.push({el,who:owner()});drainThumbs();};if('IntersectionObserver'in window){const io=new IntersectionObserver(items=>{if(items.some(i=>i.isIntersecting)){io.disconnect();observe();}});io.observe(el);}else observe();}}
