function extractFiles(obj,seen=new Map(),depth=0){if(!obj||typeof obj!=='object'||depth>9)return [...seen.values()];let key=obj.key||obj.fileKey||obj.storageKey||obj.attachmentKey;if(typeof key==='string'&&(obj.name||obj.fileName||obj.attachmentName||obj.type||obj.mime||obj.attachmentKey)){const old=seen.get(key)||{};seen.set(key,{...old,key,name:obj.name||obj.fileName||obj.attachmentName||old.name||'مرفق',type:obj.mediaType||obj.type||obj.mime||old.type,...((obj.deletedAt||old.deletedAt)?{deletedAt:obj.deletedAt||old.deletedAt,deletedBy:obj.deletedBy||old.deletedBy,deletionReason:obj.deletionReason||old.deletionReason}:{})});}for(const v of Object.values(obj))if(v&&typeof v==='object')extractFiles(v,seen,depth+1);return [...seen.values()];}
